import { useMemo, useRef, useState } from "react";
import type { ChangeEvent, ReactNode } from "react";
import * as XLSX from "xlsx";
import {
  ArrowDownToLine,
  ArrowUpFromLine,
  BarChart3,
  Bell,
  Boxes,
  CalendarDays,
  Camera,
  Check,
  ChevronDown,
  ClipboardList,
  Download,
  FileSpreadsheet,
  FileText,
  Hammer,
  HardHat,
  LayoutDashboard,
  MapPin,
  Menu,
  PackageCheck,
  Plus,
  RotateCcw,
  Search,
  Settings2,
  ShieldCheck,
  Upload,
  UsersRound,
  X,
} from "lucide-react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";

type ViewName = "dashboard" | "inventario" | "movimientos" | "configuracion" | "importar";
type ModalName = "movement" | "tool" | "unit" | "location" | "storekeeper" | "worker" | null;
type MovementType = "dispatch" | "return" | "transfer";

type Tool = {
  id: number;
  code: string;
  name: string;
  category?: string | null;
  brand?: string | null;
  model?: string | null;
  serialNumber?: string | null;
  quantity: number;
  availableQuantity: number;
  status: string;
  imageUrl?: string | null;
  locationId?: number | null;
  rotations: number;
  holder?: string | null;
  holderCode?: string | null;
  loanStorekeeper?: string | null;
  daysOut: number;
};

type Unit = { id: number; code: string; name: string; company?: string | null; site?: string | null };
type Location = { id: number; code: string; name: string; zone?: string | null; description?: string | null; unitId?: number | null; photoUrl?: string | null };
type Storekeeper = { id: number; code: string; fullName: string; employeeId?: string | null; phone?: string | null; role?: "admin" | "operator" };
type Worker = { id: number; code: string; fullName: string; area?: string | null; company?: string | null; unitId?: number | null };
type Movement = { id: number; toolId: number; workerId: number; storekeeperId: number; type: MovementType; quantity: number; occurredAt: number; destination?: string | null; condition?: string | null; note?: string | null };
type Snapshot = { units: Unit[]; locations: Location[]; storekeepers: Storekeeper[]; workers: Worker[]; tools: Tool[]; movements: Movement[]; stats: { totalStock: number; totalAvailable: number; borrowed: number; overdue: number; totalTools: number; totalMovements: number } };

type ImportPayload = { units: Array<{ code: string; name: string; company?: string; site?: string }>; locations: Array<{ code: string; name: string; zone?: string; description?: string; unitCode?: string; photoUrl?: string }>; storekeepers: Array<{ code: string; fullName: string; employeeId?: string; phone?: string; password?: string }>; workers: Array<{ code: string; fullName: string; area?: string; company?: string; unitCode?: string }>; tools: Array<{ code: string; name: string; category?: string; brand?: string; model?: string; serialNumber?: string; quantity?: number; unitCode?: string; locationCode?: string; imageUrl?: string; notes?: string }> };

const navItems: Array<{ id: ViewName; label: string; icon: typeof LayoutDashboard }> = [
  { id: "dashboard", label: "Resumen", icon: LayoutDashboard },
  { id: "inventario", label: "Inventario", icon: Boxes },
  { id: "movimientos", label: "Movimientos", icon: ClipboardList },
  { id: "configuracion", label: "Configuración inicial", icon: Settings2 },
  { id: "importar", label: "Importar Excel", icon: FileSpreadsheet },
];

const sheetHeaders: Record<string, string[]> = {
  unidades: ["codigo", "nombre", "empresa", "sitio"],
  ubicaciones: ["codigo", "nombre", "zona", "descripcion", "codigo_unidad", "foto_url"],
  almaceneros: ["codigo", "nombre_completo", "documento", "telefono", "contrasena"],
  trabajadores: ["codigo", "nombre_completo", "area", "empresa", "codigo_unidad"],
  herramientas: ["codigo", "nombre", "categoria", "marca", "modelo", "numero_serie", "cantidad", "codigo_unidad", "codigo_ubicacion", "imagen_url", "observaciones"],
};

function normaliseKey(value: unknown) { return String(value ?? "").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, "_"); }
function cell(row: Record<string, unknown>, ...keys: string[]) { const normalized = Object.fromEntries(Object.entries(row).map(([key, value]) => [normaliseKey(key), value])); for (const key of keys) if (normalized[key] !== undefined && normalized[key] !== "") return String(normalized[key]).trim(); return undefined; }
function fileToDataUrl(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); }
function dateLabel() { return new Intl.DateTimeFormat("es-PE", { weekday: "long", day: "numeric", month: "long" }).format(new Date()); }
function typeLabel(type: MovementType) { return type === "dispatch" ? "Despacho" : type === "return" ? "Recepción" : "Traslado"; }
function statusLabel(status: string) { const labels: Record<string, string> = { available: "Disponible", borrowed: "Prestada", maintenance: "Mantenimiento", lost: "Perdida", retired: "Baja" }; return labels[status] ?? status; }
function formatMovementDate(epoch: number) { return new Date(epoch).toLocaleString("es-PE", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }); }

export default function Home() {
  const { user, loading: authLoading, isAuthenticated, refresh: authRefresh } = useAuth();
  const utils = trpc.useUtils();
  const bootstrapQuery = trpc.auth.bootstrapStatus.useQuery(undefined, { enabled: !isAuthenticated, retry: false });
  const loginMutation = trpc.auth.login.useMutation({ onSuccess: () => authRefresh() });
  const registerFirstMutation = trpc.auth.registerFirst.useMutation({ onSuccess: () => refresh() });
  const snapshotQuery = trpc.catalog.snapshot.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const importMutation = trpc.catalog.import.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const unitMutation = trpc.catalog.createUnit.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const locationMutation = trpc.catalog.createLocation.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const storekeeperMutation = trpc.catalog.createStorekeeper.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const workerMutation = trpc.catalog.createWorker.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const toolMutation = trpc.catalog.createTool.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });
  const uploadMutation = trpc.catalog.uploadImage.useMutation();
  const movementMutation = trpc.movements.create.useMutation({ onSuccess: () => utils.catalog.snapshot.invalidate() });

  const snapshot = (snapshotQuery.data ?? { units: [], locations: [], storekeepers: [], workers: [], tools: [], movements: [], stats: { totalStock: 0, totalAvailable: 0, borrowed: 0, overdue: 0, totalTools: 0, totalMovements: 0 } }) as Snapshot;
  const [view, setView] = useState<ViewName>("dashboard");
  const [modal, setModal] = useState<ModalName>(null);
  const [toast, setToast] = useState("");
  const [search, setSearch] = useState("");
  const [movementType, setMovementType] = useState<MovementType>("dispatch");
  const [selectedTool, setSelectedTool] = useState<number | "">("");
  const [selectedWorker, setSelectedWorker] = useState<number | "">("");
  const [selectedStorekeeper, setSelectedStorekeeper] = useState<number | "">("");
  const [movementQty, setMovementQty] = useState(1);
  const [movementNote, setMovementNote] = useState("");
  const [movementDestination, setMovementDestination] = useState("");
  const [movementCondition, setMovementCondition] = useState("");
  const [importPreview, setImportPreview] = useState<ImportPayload | null>(null);
  const [importFileName, setImportFileName] = useState("");
  const [imagePreview, setImagePreview] = useState("");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [locationPhotoPreview, setLocationPhotoPreview] = useState("");
  const [locationPhotoFile, setLocationPhotoFile] = useState<File | null>(null);
  const [formMessage, setFormMessage] = useState("");
  const toolImageInput = useRef<HTMLInputElement>(null);
  const locationImageInput = useRef<HTMLInputElement>(null);

  const tools = snapshot.tools;
  const overdueTools = useMemo(() => tools.filter((tool) => tool.daysOut >= 7).sort((a, b) => b.daysOut - a.daysOut), [tools]);
  const filteredTools = useMemo(() => { const normalized = search.toLowerCase().trim(); return tools.filter((tool) => !normalized || [tool.code, tool.name, tool.category, tool.brand].some((value) => String(value ?? "").toLowerCase().includes(normalized))); }, [tools, search]);
  const topTools = useMemo(() => [...tools].sort((a, b) => b.rotations - a.rotations).slice(0, 5), [tools]);

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3200); };
  const refresh = async () => { await utils.catalog.snapshot.invalidate(); };
  const resetMedia = () => { setImagePreview(""); setImageFile(null); setLocationPhotoPreview(""); setLocationPhotoFile(null); if (toolImageInput.current) toolImageInput.current.value = ""; if (locationImageInput.current) locationImageInput.current.value = ""; };
  const openMovement = (type: MovementType, toolId?: number) => { setMovementType(type); setSelectedTool(toolId ?? (tools[0]?.id ?? "")); setSelectedWorker(type === "return" ? (tools.find((tool) => tool.id === toolId)?.holderCode ? snapshot.workers.find((worker) => worker.code === tools.find((tool) => tool.id === toolId)?.holderCode)?.id ?? "" : "") : (snapshot.workers[0]?.id ?? "")); setSelectedStorekeeper(snapshot.storekeepers[0]?.id ?? ""); setMovementQty(1); setMovementNote(""); setMovementDestination(""); setMovementCondition(""); setFormMessage(""); setModal("movement"); };

  const handleImage = async (event: ChangeEvent<HTMLInputElement>, kind: "tool" | "location") => { const file = event.target.files?.[0]; if (!file) return; if (!file.type.startsWith("image/")) { notify("Selecciona una imagen JPG, PNG o WEBP"); return; } if (file.size > 8 * 1024 * 1024) { notify("La imagen supera el límite de 8 MB"); return; } const data = await fileToDataUrl(file); if (kind === "tool") { setImageFile(file); setImagePreview(data); } else { setLocationPhotoFile(file); setLocationPhotoPreview(data); } };

  const handleMovement = async () => { if (!selectedTool || !selectedWorker || !selectedStorekeeper) { setFormMessage("Selecciona herramienta, trabajador y almacenero."); return; } try { await movementMutation.mutateAsync({ toolId: Number(selectedTool), workerId: Number(selectedWorker), storekeeperId: Number(selectedStorekeeper), type: movementType, quantity: movementQty, note: movementNote || undefined, destination: movementDestination || undefined, condition: movementCondition || undefined }); setModal(null); notify(`${typeLabel(movementType)} registrado correctamente`); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo registrar el movimiento."); } };

  const handleToolCreate = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { let imageUrl: string | undefined; let imageKey: string | undefined; if (imageFile) { const uploaded = await uploadMutation.mutateAsync({ fileName: imageFile.name, contentType: imageFile.type as "image/jpeg" | "image/png" | "image/webp" | "image/heic", dataUrl: imagePreview }); imageUrl = uploaded.url; imageKey = uploaded.key; } await toolMutation.mutateAsync({ code: String(form.get("code")), name: String(form.get("name")), category: String(form.get("category") || "") || undefined, brand: String(form.get("brand") || "") || undefined, model: String(form.get("model") || "") || undefined, serialNumber: String(form.get("serialNumber") || "") || undefined, quantity: Number(form.get("quantity") || 1), unitId: form.get("unitId") ? Number(form.get("unitId")) : undefined, locationId: form.get("locationId") ? Number(form.get("locationId")) : undefined, imageUrl, imageKey, notes: String(form.get("notes") || "") || undefined }); setModal(null); resetMedia(); notify("Herramienta guardada en el inventario"); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo guardar la herramienta."); } };
  const handleUnitCreate = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await unitMutation.mutateAsync({ code: String(form.get("code")), name: String(form.get("name")), company: String(form.get("company") || "") || undefined, site: String(form.get("site") || "") || undefined }); setModal(null); notify("Unidad minera guardada"); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo guardar la unidad."); } };
  const handleLocationCreate = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { let photoUrl: string | undefined; let photoKey: string | undefined; if (locationPhotoFile) { const uploaded = await uploadMutation.mutateAsync({ fileName: locationPhotoFile.name, contentType: locationPhotoFile.type as "image/jpeg" | "image/png" | "image/webp" | "image/heic", dataUrl: locationPhotoPreview }); photoUrl = uploaded.url; photoKey = uploaded.key; } await locationMutation.mutateAsync({ code: String(form.get("code")), name: String(form.get("name")), zone: String(form.get("zone") || "") || undefined, description: String(form.get("description") || "") || undefined, unitId: form.get("unitId") ? Number(form.get("unitId")) : undefined, photoUrl, photoKey }); setModal(null); resetMedia(); notify("Ubicación guardada"); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo guardar la ubicación."); } };
  const handleStorekeeperCreate = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await storekeeperMutation.mutateAsync({ code: String(form.get("code")), fullName: String(form.get("fullName")), employeeId: String(form.get("employeeId") || "") || undefined, phone: String(form.get("phone") || "") || undefined, password: String(form.get("password")) }); setModal(null); notify("Almacenero registrado"); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo guardar el almacenero."); } };
  const handleWorkerCreate = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await workerMutation.mutateAsync({ code: String(form.get("code")), fullName: String(form.get("fullName")), area: String(form.get("area") || "") || undefined, company: String(form.get("company") || "") || undefined, unitId: form.get("unitId") ? Number(form.get("unitId")) : undefined }); setModal(null); notify("Trabajador registrado"); await refresh(); } catch (error) { setFormMessage(error instanceof Error ? error.message : "No se pudo guardar el trabajador."); } };

  const handleExcel = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" }); const rows = (name: string) => { const sheetName = workbook.SheetNames.find((sheet) => normaliseKey(sheet) === name); return sheetName ? XLSX.utils.sheet_to_json<Record<string, unknown>>(workbook.Sheets[sheetName], { defval: "" }) : []; }; const units = rows("unidades").map((row) => ({ code: cell(row, "codigo", "code") ?? "", name: cell(row, "nombre", "name") ?? "", company: cell(row, "empresa", "company"), site: cell(row, "sitio", "site") })).filter((row) => row.code && row.name); const locations = rows("ubicaciones").map((row) => ({ code: cell(row, "codigo", "code") ?? "", name: cell(row, "nombre", "name") ?? "", zone: cell(row, "zona", "zone"), description: cell(row, "descripcion", "description"), unitCode: cell(row, "codigo_unidad", "unit_code"), photoUrl: cell(row, "foto_url", "photo_url") })).filter((row) => row.code && row.name); const storekeepers = rows("almaceneros").map((row) => ({ code: cell(row, "codigo", "code") ?? "", fullName: cell(row, "nombre_completo", "full_name", "nombre") ?? "", employeeId: cell(row, "documento", "employee_id"), phone: cell(row, "telefono", "phone"), password: cell(row, "contrasena", "password") })).filter((row) => row.code && row.fullName && row.password); const workers = rows("trabajadores").map((row) => ({ code: cell(row, "codigo", "code") ?? "", fullName: cell(row, "nombre_completo", "full_name", "nombre") ?? "", area: cell(row, "area"), company: cell(row, "empresa", "company"), unitCode: cell(row, "codigo_unidad", "unit_code") })).filter((row) => row.code && row.fullName); const tools = rows("herramientas").map((row) => ({ code: cell(row, "codigo", "code") ?? "", name: cell(row, "nombre", "name") ?? "", category: cell(row, "categoria", "category"), brand: cell(row, "marca", "brand"), model: cell(row, "modelo", "model"), serialNumber: cell(row, "numero_serie", "serial_number"), quantity: Number(cell(row, "cantidad", "quantity") ?? 1), unitCode: cell(row, "codigo_unidad", "unit_code"), locationCode: cell(row, "codigo_ubicacion", "location_code"), imageUrl: cell(row, "imagen_url", "image_url"), notes: cell(row, "observaciones", "notes") })).filter((row) => row.code && row.name); setImportFileName(file.name); setImportPreview({ units, locations, storekeepers, workers, tools }); } catch { notify("No se pudo leer el Excel. Descarga la plantilla y respeta las hojas y columnas."); } };
  const downloadTemplate = () => { const workbook = XLSX.utils.book_new(); Object.entries(sheetHeaders).forEach(([sheet, headers]) => XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet([headers]), sheet)); XLSX.writeFile(workbook, "plantilla_control_herramientas.xlsx"); notify("Plantilla Excel descargada"); };
  const importNow = async () => { if (!importPreview) return; try { await importMutation.mutateAsync(importPreview); setImportPreview(null); setImportFileName(""); notify("Base de datos importada correctamente"); await refresh(); setView("dashboard"); } catch (error) { notify(error instanceof Error ? error.message : "No se pudo importar la base de datos."); } };

  if (authLoading || (!isAuthenticated && bootstrapQuery.isLoading)) return <div className="ops-loading"><div className="brand-mark"><Hammer size={22} /></div><strong>Cargando Almacén+</strong><span>Verificando acceso interno…</span></div>;
  if (!isAuthenticated || !user) return <AccessGate requiresFirstRegistration={Boolean(bootstrapQuery.data?.requiresFirstRegistration)} onLogin={(code, password) => loginMutation.mutateAsync({ code, password })} onRegister={(input) => registerFirstMutation.mutateAsync(input)} pending={loginMutation.isPending || registerFirstMutation.isPending} error={loginMutation.error?.message || registerFirstMutation.error?.message || ""} />;

  const pageMeta: Record<ViewName, { eyebrow: string; title: string; description: string }> = { dashboard: { eyebrow: "Control de almacén", title: "Panel operativo", description: snapshot.stats.totalTools ? "Monitorea inventario, movimientos y devoluciones pendientes." : "Tu espacio está listo. Comienza configurando tu unidad minera." }, inventario: { eyebrow: "Catálogo operativo", title: "Inventario de herramientas", description: "Registra equipos, fotografías, cantidades y ubicación física." }, movimientos: { eyebrow: "Trazabilidad completa", title: "Despachos y recepciones", description: "Cada movimiento guarda quién entregó, quién retiró y cuándo ocurrió." }, configuracion: { eyebrow: "Puesta en marcha", title: "Configuración inicial", description: "Completa los datos maestros antes de comenzar la operación." }, importar: { eyebrow: "Carga masiva", title: "Importar base de datos", description: "Carga tu Excel respetando las hojas y columnas de la plantilla." } };
  const meta = pageMeta[view];

  return <div className="app-shell"><aside className="sidebar"><div className="brand-lockup"><div className="brand-mark"><Hammer size={22} strokeWidth={2.5} /></div><div><div className="brand-name">almacén<span>+</span></div><div className="brand-caption">control de herramientas</div></div></div><div className="warehouse-switcher"><div className="warehouse-icon"><HardHat size={18} /></div><div><span>Espacio de trabajo</span><strong>{snapshot.units[0]?.name || "Sin configurar"}</strong></div><ChevronDown size={16} /></div><div className="sidebar-label">Operación</div><nav className="main-nav">{navItems.slice(0, 3).map((item) => { const Icon = item.icon; return <button key={item.id} className={`nav-item ${view === item.id ? "active" : ""}`} onClick={() => setView(item.id)}><Icon size={18} /><span>{item.label}</span>{item.id === "movimientos" && snapshot.stats.totalMovements > 0 && <em>{snapshot.stats.totalMovements}</em>}</button>; })}</nav><div className="sidebar-label secondary-label">Configuración</div><nav className="main-nav">{navItems.slice(3).map((item) => { const Icon = item.icon; return <button key={item.id} className={`nav-item ${view === item.id ? "active" : ""}`} onClick={() => setView(item.id)}><Icon size={18} /><span>{item.label}</span></button>; })}</nav><div className="sidebar-bottom"><div className="sync-card"><div className="sync-dot"/><div><strong>Base conectada</strong><span>Datos guardados en la nube</span></div></div><div className="user-profile"><div className="avatar avatar-orange">{String(user.name || "AM").split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase()}</div><div><strong>{user.name || "Administrador"}</strong><span>{user.role === "admin" ? "Administrador" : "Usuario autorizado"}</span></div></div></div></aside><main className="main-content"><header className="topbar"><div className="breadcrumb"><span>Almacén+</span><b>/</b><strong>{meta.title}</strong></div><div className="topbar-actions"><div className="top-date"><CalendarDays size={16} /><span>{dateLabel()}</span></div><button className="icon-button" onClick={() => notify("No tienes notificaciones nuevas")} aria-label="Notificaciones"><Bell size={19} /></button><div className="mini-avatar">{String(user.name || "AM").split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase()}</div></div></header><div className="page-content"><section className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{meta.eyebrow}</div><h1>{meta.title}</h1><p>{meta.description}</p></div><div className="heading-actions"><button className="button button-light" onClick={downloadTemplate}><Download size={16} />Plantilla Excel</button><button className="button button-primary" onClick={() => setModal("tool")}><Plus size={17} />Nueva herramienta</button></div></section>{view === "dashboard" && <Dashboard snapshot={snapshot} overdueTools={overdueTools} topTools={topTools} onView={setView} onMovement={openMovement} />} {view === "inventario" && <Inventory tools={filteredTools} search={search} setSearch={setSearch} onMovement={openMovement} />} {view === "movimientos" && <Movements snapshot={snapshot} onMovement={openMovement} />} {view === "configuracion" && <Configuration snapshot={snapshot} onOpenModal={(name) => { setFormMessage(""); setModal(name); }} />} {view === "importar" && <ImportView fileName={importFileName} preview={importPreview} onFile={handleExcel} onDownload={downloadTemplate} onImport={importNow} importing={importMutation.isPending} />} </div></main>{modal === "movement" && <MovementModal snapshot={snapshot} type={movementType} setType={setMovementType} selectedTool={selectedTool} setSelectedTool={setSelectedTool} selectedWorker={selectedWorker} setSelectedWorker={setSelectedWorker} selectedStorekeeper={selectedStorekeeper} setSelectedStorekeeper={setSelectedStorekeeper} quantity={movementQty} setQuantity={setMovementQty} note={movementNote} setNote={setMovementNote} destination={movementDestination} setDestination={setMovementDestination} condition={movementCondition} setCondition={setMovementCondition} message={formMessage} onClose={() => setModal(null)} onSubmit={handleMovement} />} {modal === "tool" && <ModalShell title="Nueva herramienta" eyebrow="Alta de inventario" onClose={() => { setModal(null); resetMedia(); }}><form className="ops-form-grid" onSubmit={handleToolCreate}><Field label="Código interno" name="code" placeholder="Ej. TAL-00001" required /><Field label="Nombre" name="name" placeholder="Ej. Taladro percutor" required /><Field label="Categoría" name="category" placeholder="Manual, eléctrica, medición..." /><Field label="Marca" name="brand" placeholder="Ej. Bosch" /><Field label="Modelo" name="model" placeholder="Modelo o referencia" /><Field label="Número de serie" name="serialNumber" placeholder="Opcional" /><Field label="Cantidad inicial" name="quantity" type="number" defaultValue="1" /><SelectField label="Unidad minera" name="unitId" options={snapshot.units.map((unit) => ({ value: unit.id, label: `${unit.code} · ${unit.name}` }))} /><SelectField label="Ubicación" name="locationId" options={snapshot.locations.map((location) => ({ value: location.id, label: `${location.code} · ${location.name}` }))} /><label className="ops-field ops-full"><span>Observaciones</span><textarea name="notes" rows={2} placeholder="Accesorios, estado, notas de inventario..." /></label><MediaPicker title="Fotografía de la herramienta" preview={imagePreview} inputRef={toolImageInput} onChange={(event) => handleImage(event, "tool")} onCamera={() => { toolImageInput.current?.setAttribute("capture", "environment"); toolImageInput.current?.click(); }} onFiles={() => { toolImageInput.current?.removeAttribute("capture"); toolImageInput.current?.click(); }} /><FormFooter onClose={() => { setModal(null); resetMedia(); }} pending={toolMutation.isPending || uploadMutation.isPending} message={formMessage} submitLabel="Guardar herramienta" /></form></ModalShell>} {modal === "unit" && <SimpleFormModal title="Nueva unidad minera" eyebrow="Datos maestros" onSubmit={handleUnitCreate} onClose={() => setModal(null)} pending={unitMutation.isPending} message={formMessage}><Field label="Código" name="code" placeholder="Ej. UM-NORTE" required /><Field label="Nombre de la unidad" name="name" placeholder="Ej. Unidad Minera Norte" required /><Field label="Empresa" name="company" placeholder="Empresa titular o contratista" /><Field label="Sitio / ubicación" name="site" placeholder="Región, provincia o distrito" /></SimpleFormModal>} {modal === "location" && <ModalShell title="Nueva ubicación" eyebrow="Orden físico" onClose={() => { setModal(null); resetMedia(); }}><form className="ops-form-grid" onSubmit={handleLocationCreate}><Field label="Código" name="code" placeholder="Ej. EST-01-A03" required /><Field label="Nombre" name="name" placeholder="Ej. Estante 01" required /><Field label="Zona" name="zone" placeholder="Almacén, taller, vehículo..." /><SelectField label="Unidad minera" name="unitId" options={snapshot.units.map((unit) => ({ value: unit.id, label: `${unit.code} · ${unit.name}` }))} /><label className="ops-field ops-full"><span>Descripción</span><textarea name="description" rows={2} placeholder="Referencia y detalle de la ubicación..." /></label><MediaPicker title="Fotografía de la ubicación" preview={locationPhotoPreview} inputRef={locationImageInput} onChange={(event) => handleImage(event, "location")} onCamera={() => { locationImageInput.current?.setAttribute("capture", "environment"); locationImageInput.current?.click(); }} onFiles={() => { locationImageInput.current?.removeAttribute("capture"); locationImageInput.current?.click(); }} /><FormFooter onClose={() => { setModal(null); resetMedia(); }} pending={locationMutation.isPending || uploadMutation.isPending} message={formMessage} submitLabel="Guardar ubicación" /></form></ModalShell>} {modal === "storekeeper" && <SimpleFormModal title="Registrar almacenero" eyebrow="Responsable de movimientos" onSubmit={handleStorekeeperCreate} onClose={() => setModal(null)} pending={storekeeperMutation.isPending} message={formMessage}><Field label="Código personal" name="code" placeholder="Ej. ALM-001" required /><Field label="Nombre completo" name="fullName" placeholder="Nombres y apellidos" required /><Field label="Documento" name="employeeId" placeholder="DNI o código de empleado" /><Field label="Teléfono" name="phone" placeholder="Opcional" /><Field label="Contraseña" name="password" type="password" placeholder="Mínimo 6 caracteres" required /></SimpleFormModal>} {modal === "worker" && <SimpleFormModal title="Registrar trabajador" eyebrow="Personas autorizadas" onSubmit={handleWorkerCreate} onClose={() => setModal(null)} pending={workerMutation.isPending} message={formMessage}><Field label="Código del trabajador" name="code" placeholder="Ej. TRB-0001" required /><Field label="Nombre completo" name="fullName" placeholder="Nombres y apellidos" required /><Field label="Área" name="area" placeholder="Mantenimiento, operaciones..." /><Field label="Empresa" name="company" placeholder="Empresa o contratista" /><SelectField label="Unidad minera" name="unitId" options={snapshot.units.map((unit) => ({ value: unit.id, label: `${unit.code} · ${unit.name}` }))} /></SimpleFormModal>}{toast && <div className="toast"><div className="toast-check"><Check size={15} /></div><span>{toast}</span><button onClick={() => setToast("")}><X size={15} /></button></div>}</div>;
}

function AccessGate({ requiresFirstRegistration, onLogin, onRegister, pending, error }: { requiresFirstRegistration: boolean; onLogin: (code: string, password: string) => Promise<unknown>; onRegister: (input: { code: string; fullName: string; password: string; employeeId?: string; phone?: string }) => Promise<unknown>; pending: boolean; error: string }) {
  const [register, setRegister] = useState(requiresFirstRegistration);
  const [code, setCode] = useState(""); const [password, setPassword] = useState(""); const [fullName, setFullName] = useState(""); const [employeeId, setEmployeeId] = useState(""); const [phone, setPhone] = useState(""); const [localError, setLocalError] = useState("");
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setLocalError(""); try { if (register) await onRegister({ code, fullName, password, employeeId: employeeId || undefined, phone: phone || undefined }); else await onLogin(code, password); } catch (e) { setLocalError(e instanceof Error ? e.message : "No se pudo completar el acceso."); } };
  return <div className="ops-access"><div className="ops-access-card"><div className="brand-mark"><Hammer size={25} /></div><div className="eyebrow"><span className="eyebrow-dot" />Control interno de almacén</div><h1>{register ? "Registra al primer almacenero" : "Ingresa al almacén"}</h1><p>{register ? "No hay almaceneros registrados. Crea el primer acceso administrador con un código y contraseña." : "Ingresa con el código personal y contraseña entregados por el administrador."}</p><form className="ops-access-form" onSubmit={submit}>{register && <><Field label="Nombre completo" name="fullName" placeholder="Nombres y apellidos" required value={fullName} onChange={(e) => setFullName(e.target.value)} /><Field label="Documento" name="employeeId" placeholder="DNI o código de empleado" value={employeeId} onChange={(e) => setEmployeeId(e.target.value)} /><Field label="Teléfono" name="phone" placeholder="Opcional" value={phone} onChange={(e) => setPhone(e.target.value)} /></>}<Field label="Código de almacenero" name="code" placeholder="Ej. ALM-001" required value={code} onChange={(e) => setCode(e.target.value)} /><Field label="Contraseña" name="password" type="password" placeholder="Mínimo 6 caracteres" required value={password} onChange={(e) => setPassword(e.target.value)} />{(localError || error) && <div className="ops-form-message">{localError || error}</div>}<button className="button button-primary" type="submit" disabled={pending}><ShieldCheck size={16} />{pending ? "Procesando…" : register ? "Crear acceso administrador" : "Ingresar"}</button></form>{!requiresFirstRegistration && <button className="button button-link" type="button" onClick={() => setRegister(!register)}>{register ? "Ya existe un almacenero · Ingresar" : "Registrar primer almacenero"}</button>}<div className="ops-access-note"><Check size={14} />Sin datos de ejemplo: comenzarás con el sistema en blanco.</div></div></div>; }

function Dashboard({ snapshot, overdueTools, topTools, onView, onMovement }: { snapshot: Snapshot; overdueTools: Tool[]; topTools: Tool[]; onView: (view: ViewName) => void; onMovement: (type: MovementType, toolId?: number) => void }) { const stats = snapshot.stats; return <><section className="kpi-grid"><Kpi label="Unidades registradas" value={String(stats.totalStock)} icon={<Boxes size={20} />} tone="orange" detail={stats.totalTools ? `${stats.totalTools} fichas de herramienta` : "Comienza desde cero"} /><Kpi label="Disponibles ahora" value={String(stats.totalAvailable)} icon={<PackageCheck size={20} />} tone="teal" detail={stats.totalStock ? `${Math.round((stats.totalAvailable / stats.totalStock) * 100)}% del inventario` : "Sin inventario cargado"} /><Kpi label="En campo" value={String(stats.borrowed)} icon={<ArrowUpFromLine size={20} />} tone="blue" detail={`${snapshot.workers.length} trabajadores registrados`} /><Kpi label="Devoluciones atrasadas" value={String(stats.overdue)} icon={<Bell size={20} />} tone="red" detail="Más de 7 días fuera" /></section>{stats.totalTools === 0 ? <EmptyStart onView={onView} /> : <><section className={`ops-alert-panel ${overdueTools.length ? "has-alerts" : "clear"}`}><div className="ops-alert-heading"><div className="ops-alert-title"><div className="alert-pulse"><Bell size={17} /></div><div><div className="panel-kicker">Seguimiento automático</div><h2>{overdueTools.length ? "Herramientas con devolución atrasada" : "Sin devoluciones atrasadas"}</h2><p>{overdueTools.length ? `Hay ${overdueTools.length} herramientas fuera del almacén por más de 7 días.` : "El sistema no detecta préstamos con antigüedad crítica."}</p></div></div><button className="text-button" onClick={() => onView("movimientos")}>Ver movimientos <span>→</span></button></div>{overdueTools.length > 0 && <div className="overdue-list">{overdueTools.slice(0, 4).map((tool) => <div className="overdue-item" key={tool.id}><ToolThumb tool={tool} /><div className="overdue-tool"><strong>{tool.name}</strong><span>{tool.code} · {tool.holder || "Responsable no registrado"}</span></div><div className="overdue-holder"><span>Almacenero que entregó</span><strong>{tool.loanStorekeeper || "—"}</strong></div><div className="overdue-days"><strong>{tool.daysOut} días</strong><span>sin devolución</span></div><button className="overdue-action" onClick={() => onMovement("return", tool.id)}><ArrowDownToLine size={14} />Registrar recepción</button></div>)}</div>}</section><section className="dashboard-grid"><div className="panel activity-panel"><div className="panel-heading"><div><div className="panel-kicker">Trazabilidad</div><h2>Movimientos recientes</h2></div><button className="text-button" onClick={() => onView("movimientos")}>Ver todos <span>→</span></button></div>{snapshot.movements.length ? <div className="ops-activity-list">{snapshot.movements.slice(0, 5).map((movement) => <MovementRow key={movement.id} movement={movement} snapshot={snapshot} />)}</div> : <PanelEmpty label="Aún no hay movimientos registrados." />}</div><div className="panel rotation-panel"><div className="panel-heading"><div><div className="panel-kicker">Análisis de uso</div><h2>Mayor rotación</h2></div><button className="square-button" onClick={() => onView("inventario")} aria-label="Ver inventario"><BarChart3 size={16} /></button></div>{topTools.length ? <div className="rotation-list">{topTools.map((tool, index) => <div className="rotation-row" key={tool.id}><div className={`rank rank-${index + 1}`}>{String(index + 1).padStart(2, "0")}</div><div className="rotation-tool"><strong>{tool.name}</strong><span>{tool.code} · {tool.category || "Sin categoría"}</span></div><div className="rotation-value"><strong>{tool.rotations}</strong><span>salidas</span></div><div className="sparkbar"><i style={{ width: `${Math.max(8, (tool.rotations / Math.max(1, topTools[0].rotations)) * 100)}%` }} /></div></div>)}</div> : <PanelEmpty label="La rotación aparecerá al registrar despachos." />}</div></section></>}</>; }
function EmptyStart({ onView }: { onView: (view: ViewName) => void }) { return <section className="ops-empty-start"><div className="ops-empty-icon"><Settings2 size={25} /></div><div><div className="panel-kicker">Primer paso</div><h2>Tu almacén está en blanco</h2><p>Configura una unidad minera, registra a tus almaceneros y trabajadores, o importa todo desde Excel.</p><div className="ops-empty-actions"><button className="button button-primary" onClick={() => onView("configuracion")}><Settings2 size={16} />Configurar datos</button><button className="button button-light" onClick={() => onView("importar")}><Upload size={16} />Importar Excel</button></div></div></section>; }
function Kpi({ label, value, icon, tone, detail }: { label: string; value: string; icon: ReactNode; tone: string; detail: string }) { return <div className="kpi-card"><div className="kpi-top"><div className={`kpi-icon ${tone}`}>{icon}</div></div><div className="kpi-value">{value}</div><div className="kpi-label">{label}</div><div className="kpi-footer"><span>{detail}</span></div></div>; }
function ToolThumb({ tool }: { tool: Tool }) { return tool.imageUrl ? <img className="ops-tool-thumb" src={tool.imageUrl} alt="" /> : <div className="ops-tool-thumb placeholder"><Hammer size={16} /></div>; }
function MovementRow({ movement, snapshot }: { movement: Movement; snapshot: Snapshot }) { const tool = snapshot.tools.find((item) => item.id === movement.toolId); const worker = snapshot.workers.find((item) => item.id === movement.workerId); const storekeeper = snapshot.storekeepers.find((item) => item.id === movement.storekeeperId); return <div className="activity-row"><div className={`activity-icon ${movement.type === "return" ? "in" : movement.type === "transfer" ? "move" : "out"}`}>{movement.type === "return" ? <ArrowDownToLine size={16} /> : movement.type === "transfer" ? <RotateCcw size={16} /> : <ArrowUpFromLine size={16} />}</div><div className="activity-copy"><strong>{typeLabel(movement.type)} <span>·</span> {tool?.name || "Herramienta"}</strong><span>{worker?.fullName || "Trabajador"} · {storekeeper?.fullName || "Almacenero"}</span></div><div className="activity-time">{formatMovementDate(movement.occurredAt)}<small>{movement.quantity} ud.</small></div></div>; }
function PanelEmpty({ label }: { label: string }) { return <div className="ops-panel-empty"><ClipboardList size={20} /><span>{label}</span></div>; }

function Inventory({ tools, search, setSearch, onMovement }: { tools: Tool[]; search: string; setSearch: (value: string) => void; onMovement: (type: MovementType, toolId?: number) => void }) { return <section className="inventory-view"><div className="view-toolbar"><div className="search-field"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por código, nombre, marca..." /><kbd>⌘ K</kbd></div><button className="button button-light" onClick={() => setSearch("")}><RotateCcw size={15} />Limpiar</button></div><div className="inventory-summary"><span><strong>{tools.length}</strong> herramientas visibles</span><span className="summary-note">El inventario se completa desde Configuración o Importar Excel.</span></div>{tools.length ? <div className="inventory-grid">{tools.map((tool) => <article className="tool-card" key={tool.id}><div className="tool-card-image">{tool.imageUrl ? <img src={tool.imageUrl} alt={tool.name} /> : <div className="ops-card-placeholder"><Hammer size={30} /><span>Sin fotografía</span></div>}<span className={`status-pill ${tool.status}`}>{statusLabel(tool.status)}</span></div><div className="tool-card-content"><div className="tool-card-top"><span className="tool-code">{tool.code}</span><span className="tool-code">{tool.rotations} salidas</span></div><h3>{tool.name}</h3><p className="tool-brand">{tool.brand || "Sin marca"} <span>·</span> {tool.category || "Sin categoría"}</p><div className="tool-card-meta"><div><span>Disponibilidad</span><strong>{tool.availableQuantity} de {tool.quantity} uds.</strong></div><div><span>Ubicación</span><strong><MapPin size={13} />{tool.locationId ? `Ubicación #${tool.locationId}` : "Sin ubicar"}</strong></div></div><div className="tool-card-bottom"><span>{tool.holder ? `Con ${tool.holder}` : "En almacén"}</span><button className="overdue-action" onClick={() => onMovement("dispatch", tool.id)}><ArrowUpFromLine size={13} />Despachar</button></div></div></article>)}</div> : <div className="empty-state"><Boxes size={29} /><strong>No hay herramientas registradas</strong><span>Agrega una ficha o importa tu Excel para comenzar.</span></div>}</section>; }

function Movements({ snapshot, onMovement }: { snapshot: Snapshot; onMovement: (type: MovementType) => void }) { return <section className="data-view"><div className="view-toolbar"><div className="section-title-small"><ClipboardList size={19} /><span>Historial de movimientos</span></div><button className="button button-primary" onClick={() => onMovement("dispatch")}><Plus size={16} />Nuevo movimiento</button></div>{snapshot.movements.length ? <div className="table-wrap"><table><thead><tr><th>Tipo</th><th>Herramienta</th><th>Trabajador</th><th>Almacenero responsable</th><th>Fecha y hora</th><th>Cantidad</th><th>Observación</th></tr></thead><tbody>{snapshot.movements.map((movement) => { const tool = snapshot.tools.find((item) => item.id === movement.toolId); const worker = snapshot.workers.find((item) => item.id === movement.workerId); const storekeeper = snapshot.storekeepers.find((item) => item.id === movement.storekeeperId); return <tr key={movement.id}><td><span className={`table-type ${movement.type === "return" ? "in" : movement.type === "transfer" ? "move" : "out"}`}>{typeLabel(movement.type)}</span></td><td><strong>{tool?.name || "Herramienta"}</strong><small>{tool?.code || "—"}</small></td><td><strong>{worker?.fullName || "Trabajador"}</strong><small>{worker?.code || "—"}</small></td><td><strong>{storekeeper?.fullName || "Almacenero"}</strong><small>{storekeeper?.code || "—"}</small></td><td>{formatMovementDate(movement.occurredAt)}</td><td><strong>{movement.quantity}</strong> ud.</td><td className="note-cell">{movement.note || movement.condition || "Sin observaciones"}</td></tr>; })}</tbody></table></div> : <div className="ops-empty-large"><ClipboardList size={31} /><h2>Aún no hay movimientos</h2><p>Cuando el almacenero registre el primer despacho, aparecerá aquí toda la trazabilidad.</p><button className="button button-primary" onClick={() => onMovement("dispatch")} disabled={!snapshot.tools.length || !snapshot.workers.length || !snapshot.storekeepers.length}><Plus size={16} />Registrar primer movimiento</button></div>}</section>; }

function Configuration({ snapshot, onOpenModal }: { snapshot: Snapshot; onOpenModal: (modal: Exclude<ModalName, "movement" | "tool" | "import" | null>) => void }) { const setupCards: Array<{ key: Exclude<ModalName, "movement" | "tool" | "import" | null>; title: string; label: string; count: number; icon: ReactNode; description: string }> = [{ key: "unit", title: "Unidades mineras", label: "Unidad minera", count: snapshot.units.length, icon: <HardHat size={20} />, description: "Define el centro de operación y empresa titular." }, { key: "location", title: "Ubicaciones", label: "Ubicación", count: snapshot.locations.length, icon: <MapPin size={20} />, description: "Ordena estantes, gabinetes, talleres y vehículos." }, { key: "storekeeper", title: "Almaceneros", label: "Almacenero", count: snapshot.storekeepers.length, icon: <ShieldCheck size={20} />, description: "Registra quién entrega y recibe cada herramienta." }, { key: "worker", title: "Trabajadores", label: "Trabajador", count: snapshot.workers.length, icon: <UsersRound size={20} />, description: "Cada persona tendrá su código para retirar." }]; return <section className="setup-view"><div className="setup-banner"><div className="setup-banner-icon"><Settings2 size={22} /></div><div><strong>Configuración inicial</strong><p>Completa estos datos maestros o utiliza la importación masiva de Excel. El sistema no trae datos de ejemplo.</p></div></div><div className="setup-grid">{setupCards.map((card) => <article className="setup-card" key={card.key}><div className="setup-card-icon">{card.icon}</div><div className="setup-card-count">{card.count}</div><h2>{card.title}</h2><p>{card.description}</p><button className="button button-light" onClick={() => onOpenModal(card.key)}><Plus size={15} />Agregar {card.label.toLowerCase()}</button></article>)}</div><div className="setup-note"><FileSpreadsheet size={17} /><div><strong>¿Ya tienes la información?</strong><span>Descarga la plantilla, completa sus cinco hojas y súbela desde Importar Excel.</span></div></div></section>; }

function ImportView({ fileName, preview, onFile, onDownload, onImport, importing }: { fileName: string; preview: ImportPayload | null; onFile: (event: ChangeEvent<HTMLInputElement>) => void; onDownload: () => void; onImport: () => void; importing: boolean }) { const input = useRef<HTMLInputElement>(null); const total = preview ? preview.units.length + preview.locations.length + preview.storekeepers.length + preview.workers.length + preview.tools.length : 0; return <section className="import-view"><div className="import-layout"><div className="import-main"><div className="import-dropzone" onClick={() => input.current?.click()}><input ref={input} type="file" accept=".xlsx,.xls" onChange={onFile} hidden /><div className="import-icon"><Upload size={25} /></div><h2>{fileName || "Selecciona tu archivo Excel"}</h2><p>Arrastra o busca un archivo .xlsx / .xls con las hojas de la plantilla.</p><button className="button button-primary" type="button"><Upload size={16} />Buscar archivo</button></div>{preview && <div className="import-preview"><div className="import-preview-heading"><div><div className="panel-kicker">Vista previa lista</div><h2>{total} registros encontrados</h2><p>Revisa los conteos antes de importar. Los códigos existentes se actualizarán.</p></div><button className="button button-primary" onClick={onImport} disabled={importing}>{importing ? "Importando…" : "Importar ahora"}</button></div><div className="import-counts">{Object.entries({ Unidades: preview.units.length, Ubicaciones: preview.locations.length, Almaceneros: preview.storekeepers.length, Trabajadores: preview.workers.length, Herramientas: preview.tools.length }).map(([label, count]) => <div key={label}><strong>{count}</strong><span>{label}</span></div>)}</div></div>}</div><aside className="import-guide"><div className="import-guide-icon"><FileSpreadsheet size={21} /></div><h2>Orden de la base de datos</h2><p>El archivo debe tener estas cinco hojas. La primera fila de cada hoja debe contener exactamente los encabezados de abajo.</p>{Object.entries(sheetHeaders).map(([sheet, headers]) => <div className="sheet-guide" key={sheet}><strong>{sheet}.xlsx</strong><span>{headers.slice(0, 4).join(" · ")}{headers.length > 4 ? " · …" : ""}</span></div>)}<button className="button button-light full-button" onClick={onDownload}><Download size={15} />Descargar plantilla vacía</button></aside></div><div className="import-footnote"><ShieldCheck size={15} /><span>Importación protegida. El sistema valida códigos y guarda imágenes únicamente cuando se proporciona una URL en la columna <b>imagen_url</b>.</span></div></section>; }

function Field({ label, name, placeholder, type = "text", required = false, defaultValue, value, onChange }: { label: string; name: string; placeholder?: string; type?: string; required?: boolean; defaultValue?: string; value?: string; onChange?: (event: ChangeEvent<HTMLInputElement>) => void }) { return <label className="ops-field"><span>{label}{required && <b> *</b>}</span><input name={name} type={type} placeholder={placeholder} required={required} defaultValue={defaultValue} value={value} onChange={onChange} /></label>; }
function SelectField({ label, name, options, value, onChange }: { label: string; name: string; options: Array<{ value: number; label: string }>; value?: number | ""; onChange?: (event: ChangeEvent<HTMLSelectElement>) => void }) { return <label className="ops-field"><span>{label}</span><div className="ops-select"><select name={name} value={value ?? ""} onChange={onChange}><option value="">Sin asignar</option>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select><ChevronDown size={15} /></div></label>; }
function MediaPicker({ title, preview, inputRef, onChange, onCamera, onFiles }: { title: string; preview: string; inputRef: React.RefObject<HTMLInputElement | null>; onChange: (event: ChangeEvent<HTMLInputElement>) => void; onCamera: () => void; onFiles: () => void }) { return <div className="ops-media-picker ops-full"><span>{title}</span><input ref={inputRef} type="file" accept="image/*" onChange={onChange} hidden /><div className="ops-media-content">{preview ? <img src={preview} alt="Vista previa" /> : <div className="ops-media-placeholder"><Camera size={22} /><span>Sin fotografía seleccionada</span></div>}<div><strong>Agrega la imagen desde el celular o computador</strong><small>La cámara sirve para fotografiar la herramienta o la ubicación en el momento.</small><div className="ops-media-actions"><button type="button" className="button button-light" onClick={onCamera}><Camera size={14} />Usar cámara</button><button type="button" className="button button-light" onClick={onFiles}><Upload size={14} />Buscar archivo</button></div></div></div></div>; }
function FormFooter({ onClose, pending, message, submitLabel }: { onClose: () => void; pending: boolean; message: string; submitLabel: string }) { return <div className="ops-form-footer ops-full"><span className="ops-form-message">{message}</span><button type="button" className="button button-light" onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary" disabled={pending}>{pending ? "Guardando…" : <><Check size={15} />{submitLabel}</>}</button></div>; }
function ModalShell({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal-card ops-modal"><div className="modal-header"><div><div className="eyebrow"><span className="eyebrow-dot" />{eyebrow}</div><h2>{title}</h2><p>Completa la información para mantener el catálogo ordenado.</p></div><button className="modal-close" onClick={onClose}><X size={18} /></button></div>{children}</div></div>; }
function SimpleFormModal({ title, eyebrow, onSubmit, onClose, pending, message, children }: { title: string; eyebrow: string; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void; onClose: () => void; pending: boolean; message: string; children: ReactNode }) { return <ModalShell title={title} eyebrow={eyebrow} onClose={onClose}><form className="ops-form-grid" onSubmit={onSubmit}>{children}<FormFooter onClose={onClose} pending={pending} message={message} submitLabel="Guardar registro" /></form></ModalShell>; }
function MovementModal({ snapshot, type, setType, selectedTool, setSelectedTool, selectedWorker, setSelectedWorker, selectedStorekeeper, setSelectedStorekeeper, quantity, setQuantity, note, setNote, destination, setDestination, condition, setCondition, message, onClose, onSubmit }: { snapshot: Snapshot; type: MovementType; setType: (value: MovementType) => void; selectedTool: number | ""; setSelectedTool: (value: number | "") => void; selectedWorker: number | ""; setSelectedWorker: (value: number | "") => void; selectedStorekeeper: number | ""; setSelectedStorekeeper: (value: number | "") => void; quantity: number; setQuantity: (value: number) => void; note: string; setNote: (value: string) => void; destination: string; setDestination: (value: string) => void; condition: string; setCondition: (value: string) => void; message: string; onClose: () => void; onSubmit: () => void }) {
  const tool = snapshot.tools.find((item) => item.id === selectedTool);
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal-card ops-modal"><div className="modal-header"><div><div className="eyebrow"><span className="eyebrow-dot" />Trazabilidad del almacén</div><h2>{typeLabel(type)}</h2><p>Selecciona el trabajador y el almacenero responsable del movimiento.</p></div><button className="modal-close" onClick={onClose}><X size={18} /></button></div><div className="movement-tabs"><button type="button" className={type === "dispatch" ? "active" : ""} onClick={() => setType("dispatch")}><ArrowUpFromLine size={16} />Despacho</button><button type="button" className={type === "return" ? "active" : ""} onClick={() => setType("return")}><ArrowDownToLine size={16} />Recepción</button><button type="button" className={type === "transfer" ? "active" : ""} onClick={() => setType("transfer")}><RotateCcw size={16} />Traslado</button></div><div className="ops-form-grid"><SelectField label="Herramienta" name="tool" value={selectedTool} onChange={(event) => setSelectedTool(event.target.value ? Number(event.target.value) : "")} options={snapshot.tools.map((item) => ({ value: item.id, label: `${item.code} · ${item.name}` }))} /><SelectField label="Trabajador / código" name="worker" value={selectedWorker} onChange={(event) => setSelectedWorker(event.target.value ? Number(event.target.value) : "")} options={snapshot.workers.map((item) => ({ value: item.id, label: `${item.code} · ${item.fullName}` }))} /><SelectField label="Almacenero responsable" name="storekeeper" value={selectedStorekeeper} onChange={(event) => setSelectedStorekeeper(event.target.value ? Number(event.target.value) : "")} options={snapshot.storekeepers.map((item) => ({ value: item.id, label: `${item.code} · ${item.fullName}` }))} /><label className="ops-field"><span>Cantidad</span><div className="ops-number"><button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))}>−</button><input type="number" min="1" value={quantity} onChange={(event) => setQuantity(Math.max(1, Number(event.target.value)))} /><button type="button" onClick={() => setQuantity(quantity + 1)}>+</button></div></label><Field label="Destino / frente de trabajo" name="destination" placeholder="Opcional" value={destination} onChange={(event) => setDestination(event.target.value)} /><Field label="Condición / estado" name="condition" placeholder="Bueno, con desgaste..." value={condition} onChange={(event) => setCondition(event.target.value)} /><label className="ops-field ops-full"><span>Observaciones</span><textarea rows={2} value={note} onChange={(event) => setNote(event.target.value)} placeholder="Accesorios, daños, motivo..." /></label><div className="ops-movement-summary ops-full"><div className="ops-movement-summary-icon">{tool?.imageUrl ? <img src={tool.imageUrl} alt="" /> : <Hammer size={18} />}</div><div><strong>{tool?.name || "Selecciona una herramienta"}</strong><span>{tool ? `${tool.availableQuantity} de ${tool.quantity} disponibles · ${tool.code}` : "Sin selección"}</span></div></div><div className="ops-form-footer ops-full"><span className="ops-form-message">{message || (snapshot.storekeepers.length === 0 ? "Registra al menos un almacenero en Configuración inicial." : "")}</span><button type="button" className="button button-light" onClick={onClose}>Cancelar</button><button type="button" className="button button-primary" onClick={onSubmit}><Check size={15} />Confirmar {typeLabel(type).toLowerCase()}</button></div></div></div></div>;
}
